// Format result for user response
const inputData = $input.first().json || {};

// ALWAYS get the original context from Route by Intent to preserve chatId and other context
let originalContext = {};
try {
  const routeResult = $('Route by Intent');
  if (routeResult && routeResult.first && routeResult.first()) {
    originalContext = routeResult.first().json || {};
    console.log('Retrieved original context from Route by Intent:', {
      chatId: originalContext.chatId,
      playerName: originalContext.playerName,
      source: originalContext.source
    });
  }
} catch (e) {
  console.log('Could not get Route by Intent data:', e.message);
}

// Check if this is a chat response (direct from Route by Intent)
if (inputData.intent === 'chat' || originalContext.intent === 'chat') {
  console.log('Processing chat response');
  const chatResponse = inputData.params?.response || inputData.response || originalContext.params?.response || originalContext.response || 'Chat response received';

  return {
    json: {
      chatId: originalContext.chatId || inputData.chatId || 'unknown',
      text: chatResponse,
      conversationHistory: originalContext.conversationHistory || inputData.conversationHistory || [],
      executionResult: { type: 'chat', response: chatResponse }
    }
  };
}

// For non-chat intents, use originalContext as intentData to preserve all context
let intentData = originalContext;

// Get execution result 
let executionResult = inputData;

// Set default final message
let finalMessage = intentData.response || executionResult.message || 'Construction completed!';

// If execution failed, append error
if (executionResult.error) {
  finalMessage += `\n\n Error: ${executionResult.error}`;
} else if (executionResult.message && executionResult.message !== intentData.response) {
  finalMessage += `\n\n ${executionResult.message}`;
}

// For status/inventory, include the data
if (intentData.intent === 'stats' && executionResult.position) {
  finalMessage = `Position: x:${executionResult.position.x?.toFixed(1)}, y:${executionResult.position.y?.toFixed(1)}, z:${executionResult.position.z?.toFixed(1)}\nHealth: ${executionResult.health}/20\nHunger: ${executionResult.hunger}/20\nAction: ${executionResult.current_action || 'Idle'}`;
} else if (intentData.intent === 'inventory' && executionResult.inventory) {
  const items = Array.isArray(executionResult.inventory) ? 
    executionResult.inventory.map(item => `${item.name}(${item.count})`).join(', ') : 
    'Empty';
  finalMessage = `Inventory: ${items}`;
} else if (intentData.intent === 'nearbyBlocks' && executionResult.nearby_blocks) {
  finalMessage = `Nearby blocks: ${executionResult.nearby_blocks}`;
} else if (intentData.intent === 'entities' && executionResult.nearby_entities) {
  finalMessage = `Nearby entities: ${executionResult.nearby_entities}`;
} else if (intentData.intent === 'craftable' && executionResult.craftable_items) {
  finalMessage = `Craftable items: ${executionResult.craftable_items}`;
} else if (intentData.intent === 'modes' && executionResult.modes) {
  finalMessage = `Bot modes: ${executionResult.modes}`;
} else if (intentData.intent === 'savedPlaces' && executionResult.saved_places) {
  finalMessage = `Saved places: ${executionResult.saved_places}`;
} else if (intentData.intent === 'getCraftingPlan' && executionResult.crafting_plan) {
  finalMessage = `Crafting plan: ${executionResult.crafting_plan}`;
} else if (intentData.intent === 'lookAtPlayer' && executionResult.vision_result) {
  finalMessage = `Vision: ${executionResult.vision_result}`;
} else if (intentData.intent === 'lookAtPosition' && executionResult.vision_result) {
  finalMessage = `Vision: ${executionResult.vision_result}`;
}

// Save bot response to conversation history
const conversationHistory = intentData.conversationHistory || [];
conversationHistory.push({
  role: 'assistant',
  content: finalMessage,
  timestamp: Date.now()
});

if (conversationHistory.length > 20) {
  conversationHistory.splice(0, conversationHistory.length - 20);
}

// --- Resolve chatId directly from previous node (most reliable) ---
let chatId =
  inputData.chatId ||               // from previous node
  intentData.chatId ||              // fallback if merged
  originalContext.chatId ||         // from Route by Intent (if available)
  inputData.conversationId ||       // fallback alias
  'unknown';

console.log('Resolved chatId (from previous node):', chatId);

return {
  json: {
    chatId,
    text: finalMessage,
    conversationHistory,
    executionResult
  }
};

// Format Building Response for Telegram
const input = $input.first().json;

console.log('=== FORMAT BUILDING RESPONSE ===');
console.log('Smart AI Response:', JSON.stringify(input, null, 2));

// Get conversation data from Route by Intent node
let conversationData = {};
try {
  const routeResult = $('Route by Intent');
  if (routeResult && routeResult.first && routeResult.first()) {
    conversationData = routeResult.first().json || {};
    console.log('Retrieved conversation data from Route by Intent:', {
      chatId: conversationData.chatId,
      playerName: conversationData.playerName,
      source: conversationData.source
    });
  }
} catch (e) {
  console.log('Could not get Route by Intent data:', e);
}

// Parse smart AI API response
const apiSuccess = input.success || false;
const userMessage = input.userMessage || '';
const executionResult = input.executionResult || 'No execution details';
const apiMessage = input.message || '';

// Create formatted response message
let responseMessage = '';
if (apiSuccess) {
  // Check if the AI provided clarification or alternative suggestions
  if (executionResult.toLowerCase().includes('not possible') || 
      executionResult.toLowerCase().includes('alternative') ||
      executionResult.toLowerCase().includes('instead')) {
    responseMessage = ` **Smart AI Response**\n\n` +
                     ` **Your Request:** ${userMessage.substring(0, 100)}${userMessage.length > 100 ? '...' : ''}\n\n` +
                     ` **AI Analysis:** ${executionResult.substring(0, 300)}${executionResult.length > 300 ? '...' : ''}\n\n` +
                     ` The AI has analyzed your request and provided intelligent feedback!`;
  } else {
    responseMessage = ` **Building Task Completed!**\n\n` +
                     ` **Request:** ${userMessage.substring(0, 100)}${userMessage.length > 100 ? '...' : ''}\n\n` +
                     ` **Status:** ${apiMessage}\n\n` +
                     ` **AI Execution:** ${executionResult.substring(0, 200)}${executionResult.length > 200 ? '...' : ''}\n\n` +
                     ` The smart AI successfully processed your building request!`;
  }
} else {
  const errorMessage = input.error || input.details || 'Unknown error occurred';
  responseMessage = ` **Building Task Failed**\n\n` +
                   ` **Request:** ${userMessage.substring(0, 100)}${userMessage.length > 100 ? '...' : ''}\n\n` +
                   ` **Error:** ${errorMessage}\n\n`;

  if (executionResult && executionResult !== 'No execution details') {
    responseMessage += ` **AI Response:** ${executionResult.substring(0, 200)}${executionResult.length > 200 ? '...' : ''}\n\n`;
  }

  responseMessage += ` **Tip:** The AI might have suggestions or alternatives. Check the response above!`;
}

console.log('Formatted response:', responseMessage);

// Return formatted response with conversation data for Telegram
return {
  json: {
    chatId: conversationData.chatId || input.chatId || 'unknown',
    text: responseMessage,
    playerName: conversationData.playerName || 'User',
    source: conversationData.source || 'telegram',
    conversationHistory: conversationData.conversationHistory || [],
    executionResult: {
      type: 'smart_ai_building',
      success: apiSuccess,
      response: responseMessage,
      apiResult: input,
      aiResponse: executionResult
    }
  }
};

// Parse Smart Building Planner JSON Response
const input = $input.first().json;

console.log('=== PARSE SMART BUILDING PLANNER ===');
console.log('Raw AI Response:', JSON.stringify(input, null, 2));

// Get the AI response output
let aiResponse = input.output || input.text || input.response || '';
console.log('AI Response Text:', aiResponse);

// Try to parse JSON from the AI response
let parsedData = null;
try {
  // Clean up the response - sometimes AI adds extra text
  let jsonText = aiResponse.trim();

  // Look for JSON block in the response
  const jsonStart = jsonText.indexOf('{');
  const jsonEnd = jsonText.lastIndexOf('}');

  if (jsonStart !== -1 && jsonEnd !== -1 && jsonEnd > jsonStart) {
    jsonText = jsonText.substring(jsonStart, jsonEnd + 1);
  }

  console.log('Extracted JSON text:', jsonText);
  parsedData = JSON.parse(jsonText);
  console.log('Parsed JSON successfully:', parsedData);

} catch (e) {
  console.log('Failed to parse JSON, treating as plain text:', e.message);
  // Fallback: treat as plain text and determine execution type
  parsedData = {
    refinedPrompt: aiResponse,
    executionType: 'single' // default to single bot execution
  };
}

// Validate the parsed data
if (!parsedData.refinedPrompt) {
  parsedData.refinedPrompt = aiResponse || 'No prompt provided';
}

if (!parsedData.executionType) {
  parsedData.executionType = 'single';
}

// Ensure valid execution type
if (parsedData.executionType !== 'collaborativeBuild' && parsedData.executionType !== 'newAction') {
  parsedData.executionType = 'newAction';
}

console.log('Final parsed data:', parsedData);

// Get conversation context from Route by Intent
let conversationData = {};
try {
  const routeResult = $('Route by Intent');
  if (routeResult && routeResult.first && routeResult.first()) {
    conversationData = routeResult.first().json || {};
  }
} catch (e) {
  console.log('Could not get Route by Intent data:', e);
}

// Return the parsed data with conversation context
return {
  json: {
    refinedPrompt: parsedData.refinedPrompt,
    executionType: parsedData.executionType,
    chatId: conversationData.chatId || 'unknown',
    playerName: conversationData.playerName || 'User',
    source: conversationData.source || 'telegram',
    conversationHistory: conversationData.conversationHistory || [],
    originalRequest: conversationData.params?.prompt || conversationData.params?.buildRequest || '',
    workerCount: parsedData.workerCount || conversationData.params?.workerCount || 3,
    params: {
      buildRequest: parsedData.refinedPrompt,
      workerCount: parsedData.workerCount || conversationData.params?.workerCount || 3,
      prompt: parsedData.refinedPrompt
    }
  }
};

// === PARSE AI AGENT RESPONSE ===
const aiResponse = $input.first().json;

console.log('=== PARSE AI AGENT RESPONSE ===');
console.log('AI Agent Response:', JSON.stringify(aiResponse, null, 2));

let responseText = '';
let needsClarification = false;
let clarificationQuestion = '';
let parsedIntent = null;
let parsedParams = {};
let conversationState = 'executing';

// AI Agent returns data in 'output' field as JSON string
// Handle multiple possible formats:
// 1. Single object: {"output": "JSON_STRING"}
// 2. Array format: [{"output": "JSON_STRING"}]
// 3. Direct content formats
if (aiResponse.output) {
  responseText = aiResponse.output;
  console.log('Extracted from single object format');
} else if (Array.isArray(aiResponse) && aiResponse.length > 0) {
  if (aiResponse[0].output) {
    // Handle array format: [{"output": "JSON_STRING"}]
    responseText = aiResponse[0].output;
    console.log('Extracted from array format:', responseText);
  } else if (aiResponse[0].message && aiResponse[0].message.content) {
    responseText = aiResponse[0].message.content;
  } else {
    responseText = JSON.stringify(aiResponse[0]);
  }
} else if (aiResponse.message && aiResponse.message.content) {
  responseText = aiResponse.message.content;
} else if (aiResponse.text) {
  responseText = aiResponse.text;
} else if (aiResponse.content) {
  responseText = aiResponse.content;
} else {
  responseText = JSON.stringify(aiResponse);
}

console.log('Final extracted response text:', responseText);

// Try to parse JSON response for intent and parameters
try {
  let parsed;

  // Try to parse as direct JSON first (AI Agent often returns clean JSON)
  try {
    parsed = JSON.parse(responseText);
    console.log('Successfully parsed direct JSON:', parsed);
  } catch (e) {
    // If direct parse fails, look for JSON pattern in text
    console.log('Direct JSON parse failed, trying pattern match');
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
      console.log('Successfully parsed extracted JSON:', parsed);
    } else {
      throw new Error('No JSON pattern found');
    }
  }

  // Handle different AI response formats
  if (parsed.intent) {
    // Standard format: {"intent": "action", "params": {...}, "response": "..."}
    parsedIntent = parsed.intent;
    parsedParams = parsed.params || parsed.parameters || {};

    // Check for casual conversation intents that should be treated as chat
    if (['greetings', 'greeting', 'hello', 'hi', 'casual', 'smalltalk'].includes(parsedIntent.toLowerCase())) {
      console.log('Converting greeting/casual intent to chat');
      parsedIntent = 'chat';
      parsedParams = { response: parsed.response || parsed.params?.response || parsed.parameters?.response || 'Hello! How can I help you in Minecraft today?' };
    }

    // Also extract response from top level if available
    if (parsed.response && !parsedParams.response) {
      parsedParams.response = parsed.response;
    }
  } else if (parsed.chat) {
    // Chat format: {"chat": "message"}
    parsedIntent = 'chat';
    parsedParams = { response: parsed.chat };
  } else if (parsed.clarification) {
    // Clarification format: {"clarification": "question"}
    parsedIntent = 'clarification';
    parsedParams = { response: parsed.clarification };
  } else {
    // Unknown format, use first key as intent type
    const firstKey = Object.keys(parsed)[0];
    if (firstKey) {
      parsedIntent = firstKey;
      parsedParams = { response: parsed[firstKey] };
    }
  }

  console.log('Final parsed intent:', parsedIntent);
  console.log('Final parsed params:', parsedParams);

  // Check if the AI is asking for clarification
  if (parsed.needsClarification || parsed.clarification || 
      (parsed.response && (parsed.response.includes('?') || parsed.response.includes('clarify') || parsed.response.includes('specify')))) {
    needsClarification = true;
    clarificationQuestion = parsed.clarificationQuestion || parsed.response || 'Could you provide more details?';
    // Set intent to clarification if not already set
    if (!parsedIntent) {
      parsedIntent = 'clarification';
    }
    conversationState = 'clarifying';
    console.log('AI needs clarification:', clarificationQuestion);
  }

  // Handle clarification responses - when user provides more context in clarifying state
  // Check both AI response and original input context for conversation state
  const inputConversationState = $('Prepare Conversation Context').first()?.json?.conversationState;
  if ((aiResponse.conversationState === 'clarifying' || inputConversationState === 'clarifying') && parsedIntent && parsedIntent !== 'clarification' && parsedIntent !== 'chat') {
    console.log('User provided clarification, AI determined intent:', parsedIntent);
    needsClarification = false;
    conversationState = 'executing';
  }

  // Check if required parameters are missing for certain intents
  if (parsedIntent && !needsClarification) {
    const requiredParams = {
      'move': ['x', 'y', 'z'],
      'goToPlayer': ['player'],
      'collectBlocks': ['block'],
      'placeBlocks': ['material'],
      'craft': ['item'],
      'givePlayer': ['player', 'item'],
      'newAction': ['prompt']
    };

    const required = requiredParams[parsedIntent];
    if (required) {
      const missingParams = required.filter(param => !parsedParams[param] && parsedParams[param] !== 0);
      console.log(`Parameter validation for ${parsedIntent}:`, {
        required,
        parsedParams,
        missingParams
      });
      if (missingParams.length > 0) {
        needsClarification = true;
        clarificationQuestion = `I need more information. Please specify: ${missingParams.join(', ')}`;
        conversationState = 'clarifying';
        console.log('Missing required parameters:', missingParams);
      }
    }
  }
} catch (e) {
  console.log('Failed to parse JSON, treating as chat response:', e.message);
  parsedIntent = 'chat';
  parsedParams = { response: responseText };
}

// Get conversation context for clarification tracking
// Use original data if AI response doesn't have conversation history
const originalData = $('Prepare Conversation Context').first().json || {};
const conversationHistory = aiResponse.conversationHistory || originalData.turns || [];
let clarificationCount = originalData.clarificationCount || 0;
// Fallback: count questions in history if clarificationCount not available
if (!originalData.clarificationCount) {
  clarificationCount = conversationHistory.filter(turn => 
    turn.role === 'assistant' && turn.content && turn.content.includes('?')
  ).length;
}

// Limit clarification attempts
const maxClarifications = 3;
if (clarificationCount >= maxClarifications && needsClarification) {
  console.log('Max clarification attempts reached, proceeding with available info');
  needsClarification = false;
  conversationState = 'executing';
  if (!parsedIntent || parsedIntent === 'chat') {
    parsedIntent = 'chat';
    parsedParams = { response: 'I will do my best with the information provided.' };
  }
}

// originalData already declared above for clarification tracking

return {
  json: {
    // Preserve ALL original context data
    ...originalData,
    // Add parsed AI response data
    intent: parsedIntent,
    params: parsedParams,
    response: parsedParams.response || responseText,
    needsClarification,
    clarificationQuestion,
    conversationState,
    clarificationCount,
    originalResponse: responseText,
    // Preserve AI response for debugging
    aiResponse: aiResponse,
    // Debug info
    parsedSuccessfully: !!parsedIntent
  }
};

const input = $input.first().json;

console.log('=== PREPARE CONVERSATION CONTEXT ===');
console.log('Input structure:', Object.keys(input));
console.log('Full JSON from MongoDB:', JSON.stringify(input, null, 2));

// Get conversation data from the previous Load Conversation History node
const conversation = input.conversation || {};
const turns = input.conversationHistory || [];
const memory = input.memory || '';

console.log('Conversation loaded:', {
  conversationId: conversation.conversationId,
  turnsCount: turns.length,
  hasMemory: !!memory,
  conversationState: input.conversationState || 'initial'
});

// Use current data with fallback to stored data
const botStatus = input.botStatus || {};
const botInventory = input.botInventory || [];
const nearbyPlayers = input.nearbyPlayers || [];

const playerName = input.playerName || input.username || 'Player';
const message = input.message || '';

// Enhanced context building from database
const conversationState = input.conversationState || 'initial';
const needsClarification = input.needsClarification || false;
const clarificationCount = input.clarificationCount || 0;

console.log('Conversation state:', conversationState);
console.log('Total turns:', turns.length);
console.log('Memory length:', memory.length);

// Build comprehensive system prompt matching codebase capabilities
let systemPrompt = `You are a helpful Minecraft assistant. You can see, move, mine, build, craft, and interact with the world by using commands. You also have access to vision. Use vision when you're unsure what's in front of you, looking for resources, verifying something built, or navigating new areas. Your goal is to assist the user efficiently and accurately.

Speak concisely and avoid unnecessary filler. Do not act playful or in-character. Do not apologize unless something is truly wrong. Focus on being useful and responsive. When asked about your limitations, be honest and factual.

IMPORTANT: You must respond with a structured JSON output that contains an intent and parameters. The current speaker is "${playerName}". When they say "me" or "myself", use "${playerName}" as the player parameter.

If you need clarification on any parameters or details, respond with:
{
  "needsClarification": true,
  "clarificationQuestion": "What specific details do you need?",
  "response": "I need more information to help you properly."
}

When you have enough information to proceed, use the standard format:
{
  "intent": "intentName",
  "params": { "param1": "value1" },
  "response": "Brief response about what I will do"
}

For place block requests:
- If user says "place a block" and you have inventory items, use the first available material
- If user specifies a material, use that material  
- Default to placing at current location unless coordinates specified
- Only ask for clarification if no inventory items available

For complete requests, map user requests to the correct intents based on task complexity:

COMPLEX BUILDING/CONSTRUCTION → Use "newAction" intent:
- "build a wall", "make a house", "create a structure"
- "build a [size] [structure] using [material]"
- Any multi-step construction that needs planning and loops

SIMPLE MOVEMENT → Use "move" intent:
- "go to", "move to [coordinates]", "walk [direction]"

STATUS/INFO → Use specific query intents:
- "what's your status" → "stats" intent
- "what's in inventory" → "inventory" intent

Available intents:

MOVEMENT INTENTS:
- "move" - Move to coordinates or direction (params: x, y, z OR direction)
- "goToPlayer" - Go to a specific player (params: player, closeness)
- "followPlayer" - Follow a player (params: player, distance)
- "moveAway" - Move away from threats (params: distance)
- "searchForBlock" - Find specific blocks (params: block, range)
- "searchForEntity" - Find entities/players (params: entity, range)

BLOCK OPERATION INTENTS:
- "collectBlocks" - Mine/collect blocks (params: block, quantity)
- "placeBlocks" - Place blocks at location (params: material, x, y, z, face)
- "digDown" - Mine downward (params: depth)
- "activate" - Use blocks/buttons/levers (params: x, y, z)

ITEM MANAGEMENT INTENTS:
- "equip" - Equip items/armor (params: item)
- "discard" - Drop unwanted items (params: item, quantity)
- "consume" - Eat food/drink potions (params: item, quantity)
- "givePlayer" - Transfer items to players (params: player, item, quantity)

CHEST OPERATIONS INTENTS:
- "putInChest" - Store items in chest (params: item, quantity, x, y, z)
- "takeFromChest" - Retrieve items from chest (params: item, quantity, x, y, z)
- "viewChest" - Check chest contents (params: x, y, z)

CRAFTING INTENTS:
- "craft" - Craft recipes (params: item, quantity)
- "smelt" - Smelt items in furnace (params: item, quantity)
- "clearFurnace" - Clean furnaces

COMBAT INTENTS:
- "attackPlayer" - Engage in combat (params: player)
- "defendSelf" - Defensive actions (params: range)

MEMORY & NAVIGATION INTENTS:
- "rememberHere" - Save current location (params: name)
- "goToRememberedPlace" - Return to saved places (params: name)
- "savedPlaces" - List saved locations

INFORMATION INTENTS:
- "nearbyBlocks" - Scan environment
- "craftable" - Check craftable items  
- "entities" - List nearby entities
- "modes" - Check bot modes
- "getCraftingPlan" - Calculate crafting requirements (params: item, quantity)
- "stats" - Get bot status
- "inventory" - Check inventory

MODE MANAGEMENT INTENTS:
- "setMode" - Toggle bot behaviors (params: mode, enabled)
- "stay" - Wait/pause actions (params: seconds)
- "goToBed" - Sleep functionality

UTILITY INTENTS:
- "useDoor" - Operate doors (params: x, y, z optional)
- "newAction" - Custom AI actions (params: prompt)
- "lookAtPlayer" - Vision system (params: player, direction)
- "lookAtPosition" - Look at coordinates (params: x, y, z)

COMMUNICATION INTENTS:
- "startConversation" - Begin bot conversations (params: player, message)
- "endConversation" - End conversations (params: player)

CONTROL INTENTS:
- "restart" - Restart the agent
- "clearChat" - Clear chat history
- "endGoal" - Stop current goals
- "stop" - Force stop all actions
- "chat" - Simple conversation response (params: response)`;

// Add current bot status to system prompt
if (botStatus && Object.keys(botStatus).length > 0) {
  let statusText = 'Status unavailable';
  if (botStatus.position) {
    statusText = `Position: x:${botStatus.position.x?.toFixed(1)}, y:${botStatus.position.y?.toFixed(1)}, z:${botStatus.position.z?.toFixed(1)} | Health: ${botStatus.health}/20 | Action: ${botStatus.current_action || 'Idle'}`;
  }
  systemPrompt += `\n\nCurrent Status: ${statusText}`;
}

// Add inventory info if available
if (botInventory && Array.isArray(botInventory) && botInventory.length > 0) {
  const inventoryText = botInventory.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
  systemPrompt += `\nCurrent Inventory: ${inventoryText}`;
} else {
  systemPrompt += `\nCurrent Inventory: Empty (Creative Mode)`;
}

// Add nearby players info
if (nearbyPlayers && nearbyPlayers.length > 0) {
  systemPrompt += `\nNearby Players: ${nearbyPlayers.join(', ')}`;
} else {
  systemPrompt += `\nNearby Players: None detected`;
}

// Add conversation memory if available
if (memory.trim()) {
  systemPrompt += `\n\nConversation Memory: ${memory}`;
}

// Add clarification context if in clarification state
if (conversationState === 'clarifying') {
  systemPrompt += `\n\nIMPORTANT: You are currently in clarification mode (attempt ${clarificationCount + 1}/3). The user's previous request needed more details. Based on their response, either:
1. If you now have enough information, proceed with the appropriate intent
2. If still unclear, ask ONE specific clarifying question
3. If this is attempt 3, proceed with best effort using available information`;
}

// Build messages array following codebase History.getHistory() pattern
const messages = [];

// Add enhanced system message
messages.push({
  role: 'system',
  content: systemPrompt
});

// Add conversation history - smart context management
const maxContextTurns = 15; // Increased from 10 for better context
let contextTurns = turns.slice(-maxContextTurns);

// If we have memory but limited context, add a memory summary message
if (turns.length > maxContextTurns && memory.trim()) {
  messages.push({
    role: 'system',
    content: `Previous conversation summary: ${memory}`
  });
}

// Add recent conversation turns
for (const turn of contextTurns) {
  // Ensure proper role mapping
  let role = 'user';
  if (turn.role === 'assistant' || turn.role === 'bot') {
    role = 'assistant';
  } else if (turn.role === 'system') {
    role = 'system';
  }

  messages.push({
    role: role,
    content: turn.content || turn.message || ''
  });
}

// Add current user message if not already in recent history
const recentMessages = contextTurns.slice(-3);
const alreadyIncluded = recentMessages.some(turn => 
  turn.content === message || turn.content === `${playerName}: ${message}`
);

if (!alreadyIncluded && message) {
  messages.push({
    role: 'user', 
    content: `${playerName}: ${message}`
  });
}

// Log comprehensive context info
console.log('Enhanced conversation context prepared:', {
