if (inventoryHttpResponse) {
  // Handle array response format
  if (Array.isArray(inventoryHttpResponse)) {
    console.log('Inventory is array format');

    for (const item of inventoryHttpResponse) {
      if (item && item.inventory) {
        // Parse inventory text format
        const inventoryText = item.inventory;
        console.log('Parsing inventory text:', inventoryText);

        // Extract items from inventory text
        // Format: "- glass: 1" or "- item_name: quantity"
        const itemMatches = inventoryText.match(/- ([^:]+): (\d+)/g);
        if (itemMatches) {
          for (const match of itemMatches) {
            const parts = match.replace('- ', '').split(': ');
            if (parts.length === 2) {
              botInventory.push({
                name: parts[0].trim(),
                count: parseInt(parts[1]),
                type: parts[0].trim()
              });
            }
          }
        }

        // Check if creative mode
        if (inventoryText.includes('creative mode')) {
          console.log('Bot is in creative mode - unlimited items available');
        }
      }
