return {
  json: {
    username,        // This is now the ACTUAL in-game player name
    message,
    chatId,
    conversationHistory,
    botMemory,
    timestamp: Date.now(),
    source: source,
    playerName: username  // Explicit field for the in-game player name
  }
};

